<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from "vue";
import { f7Page, f7 } from "framework7-vue";
import { useSync } from "@/modules/sync/composables/useSync";

const { progress, isSyncing, currentTable, errors, hasError, startSync, state } = useSync();
const particlesCanvas = ref<HTMLCanvasElement | null>(null);
let animationFrameId: number;

// Particle System
class Particle {
  x: number;
  y: number;
  vx: number;
  vy: number;
  size: number;
  alpha: number;

  constructor(width: number, height: number) {
    this.x = Math.random() * width;
    this.y = Math.random() * height;
    this.vx = (Math.random() - 0.5) * 0.5;
    this.vy = (Math.random() - 0.5) * 0.5;
    this.size = Math.random() * 2;
    this.alpha = Math.random() * 0.5 + 0.1;
  }

  update(width: number, height: number) {
    this.x += this.vx;
    this.y += this.vy;

    if (this.x < 0) this.x = width;
    if (this.x > width) this.x = 0;
    if (this.y < 0) this.y = height;
    if (this.y > height) this.y = 0;
  }

  draw(ctx: CanvasRenderingContext2D) {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
    ctx.fillStyle = `rgba(14, 165, 233, ${this.alpha})`; // Sky blue
    ctx.fill();
  }
}

const initParticles = () => {
  const canvas = particlesCanvas.value;
  if (!canvas) return;

  const ctx = canvas.getContext("2d");
  if (!ctx) return;

  const updateSize = () => {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
  };

  updateSize();
  window.addEventListener("resize", updateSize);

  const particles: Particle[] = Array.from(
    { length: 150 },
    () => new Particle(canvas.width, canvas.height),
  );

  const animate = () => {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    particles.forEach((p) => {
      p.update(canvas.width, canvas.height);
      p.draw(ctx);
    });

    // Draw connections
    particles.forEach((p1, i) => {
      particles.slice(i + 1).forEach((p2) => {
        const dx = p1.x - p2.x;
        const dy = p1.y - p2.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < 100) {
          ctx.beginPath();
          ctx.strokeStyle = `rgba(14, 165, 233, ${0.1 * (1 - dist / 100)})`;
          ctx.lineWidth = 0.5;
          ctx.moveTo(p1.x, p1.y);
          ctx.lineTo(p2.x, p2.y);
          ctx.stroke();
        }
      });
    });

    animationFrameId = requestAnimationFrame(animate);
  };

  animate();

  return () => {
    window.removeEventListener("resize", updateSize);
    cancelAnimationFrame(animationFrameId);
  };
};

let cleanupParticles: (() => void) | undefined;

// Circle config
const radius = 70;
const circumference = radius * 2 * Math.PI;

const strokeDashoffset = computed(() => {
  return circumference - (progress.value / 100) * circumference;
});

// Dynamic Text
const currentTableText = computed(() => {
  return currentTable.value || "Initializing...";
});

const currentActionText = computed(() => {
  if (progress.value === 100) return "Synchronization Complete";
  if (!isSyncing.value && !hasError.value) return "Starting Sync...";
  if (hasError.value) return "Sync Interrupted";
  return "Processing Data";
});

const subStatusText = computed(() => {
  if (progress.value === 100) return "Entering Workspace";
  if (hasError.value) return `${errors.value.length} Errors Detected`;

  const { currentStep } = state.value.progress;
  if (currentStep === 1) return "Analysing Changes";
  if (currentStep === 2) return "Downloading Data";
  if (currentStep === 3) return "Applying Updates";
  return "Please Wait";
});

// Navigation
watch(progress, (newVal) => {
  if (newVal >= 100) {
    setTimeout(() => {
      // Use Framework7 router for transition
      f7.views.main.router.navigate("/", {
        reloadCurrent: true,
        transition: "f7-fade",
      });
    }, 1200);
  }
});

// Retry
const retrySync = () => {
  startSync();
};

onMounted(() => {
  cleanupParticles = initParticles();

  if (!isSyncing.value && progress.value < 100) {
    startSync();
  }
});

onUnmounted(() => {
  if (cleanupParticles) cleanupParticles();
});
</script>

